 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 == 3 and c1 - c0 == 3:
                top_gaps = [x for x in range(c0, c1 + 1) if grid[r0][x] != 5]
                if len(top_gaps) == 1:
                    gap = top_gaps[0]
                    # Fill the hollow center of the frame.
                    for y in range(r0 + 1, r1):
                        for x in range(c0 + 1, c1):
                            if grid[y][x] == 0:
                                out[y][x] = 2
                    # The missing top segment emits a beam leftward above the frame.
                    if r0 > 0:
                        for x in range(0, gap + 1):
                            if grid[r0 - 1][x] == 0:
                                out[r0 - 1][x] = 2
    return out

